package com.cpf.batch.agent.internal; import com.cpf.batch.agent.AgentProperties; import java.io.*; import java.nio.file.*; import java.security.*; import java.security.spec.X509EncodedKeySpec; import java.util.*;
public final class ArtifactVerifier { private final AgentProperties p;public ArtifactVerifier(AgentProperties p){this.p=p;} public void verify(Path file,String expected,String sig)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=Files.newInputStream(file)){byte[] b=new byte[8192];int n;while((n=in.read(b))>=0)d.update(b,0,n);}String actual=HexFormat.of().formatHex(d.digest());if(!actual.equalsIgnoreCase(expected))throw new SecurityException("checksum mismatch");if(p.isRequireSignature()){if(sig==null||sig.isBlank())throw new SecurityException("signature required");String pem=Files.readString(Path.of(p.getArtifactPublicKeyPath())).replace("-----BEGIN PUBLIC KEY-----","").replace("-----END PUBLIC KEY-----","").replaceAll("\\s","");PublicKey key=KeyFactory.getInstance("Ed25519").generatePublic(new X509EncodedKeySpec(Base64.getDecoder().decode(pem)));Signature s=Signature.getInstance("Ed25519");s.initVerify(key);s.update(expected.toLowerCase().getBytes(java.nio.charset.StandardCharsets.UTF_8));if(!s.verify(Base64.getDecoder().decode(sig)))throw new SecurityException("signature invalid");}} }
